// We sort the arrays according to the 
// elements at their second column.

double[][] values =
{   //                 v
    new double[] {  0, 3, 0 },
    new double[] {  0, 4, 1 },
    new double[] { -1, 1, 1 },
    new double[] { -1, 5, 4 },
    new double[] { -2, 2, 6 },
};

// Sort the array considering only the second column
Array.Sort(values, new ElementComparer() { Index = 1 });

// The result will be
double[][] result =
{
    new double[] { -1, 1, 1 },
    new double[] { -2, 2, 6 },
    new double[] {  0, 3, 0 },
    new double[] {  0, 4, 1 },
    new double[] { -1, 5, 4 },
};

